const income = Number(annualIncome) || 0;
const down = Number(downPayment) || 0;
const r = (Number(mortgageRatePct) || 0) / 100 / 12;
const debt = Number(monthlyDebt) || 0;
const monthlyIncome = income / 12;
const maxHousing = monthlyIncome * 0.28;
const maxTotal = monthlyIncome * 0.36 - debt;
const maxPayment = Math.max(0, Math.min(maxHousing, maxTotal));
const n = 360;
const maxLoan = r > 0 ? maxPayment * (1 - Math.pow(1 + r, -n)) / r : maxPayment * n;
const maxHomePrice = maxLoan + down;
const priceToIncome = income > 0 ? maxHomePrice / income : 0;
return { priceToIncome, maxHomePrice, maxPayment, maxLoan };

